using System.Text.Json;
namespace LeoLauncher;
sealed partial class TodoView
{
    public Dictionary<string,bool> PreviewTheme(string image){var checks=new Dictionary<string,bool>();repeatButton.PerformClick();Application.DoEvents();checks["repeat_menu_has_room_for_text_and_checkmark"]=repeatMenu.Width>=244;checks["repeat_and_series_menus_use_barca_theme"]=repeatMenu.Renderer is BarcaMenuRenderer&&seriesMenu.Renderer is BarcaMenuRenderer;using(var b=new Bitmap(repeatMenu.Width,repeatMenu.Height)){repeatMenu.DrawToBitmap(b,repeatMenu.ClientRectangle);b.Save(image);}repeatMenu.Items[1].PerformClick();repeatMenu.Close();checks["daily_menu_choice_updates_selected_mode"]=repeatMode=="daily"&&repeatButton.Text.StartsWith("每天");repeatButton.PerformClick();Application.DoEvents();checks["selected_daily_item_is_marked"]=((ToolStripMenuItem)repeatMenu.Items[1]).Checked&&!((ToolStripMenuItem)repeatMenu.Items[0]).Checked;repeatMenu.Items[2].PerformClick();repeatMenu.Close();entry.Text="主题重复测试";Add();checks["themed_menu_selection_creates_weekly_rule"]=store.Items.Any(t=>t.SeriesId!=null&&store.RuleFor(t.SeriesId)?.Frequency=="weekly");return checks;}
}
static class PlannerThemeTests
{
    static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var nested in All(c))yield return nested;}}
    public static void Save(string report){string dir=Path.GetDirectoryName(report)!;using var window=new TodoForm(true);window.Show();Application.DoEvents();var checks=window.View.PreviewTheme(Path.Combine(dir,"preview-repeat-menu.png"));var deck=new QuoteDeck();var round=Enumerable.Range(0,QuoteDeck.Lines.Length).Select(_=>deck.Next()).ToArray();checks["quote_round_has_no_repeats"]=round.Distinct().Count()==QuoteDeck.Lines.Length;checks["new_round_does_not_repeat_previous_last_line"]=deck.Next()!=round[^1];var identity=All(window).OfType<PlannerIdentity>().Single();string initial=identity.CurrentQuote;identity.PreviewNext();var until=DateTime.UtcNow.AddMilliseconds(600);while(DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(10);}checks["quote_changes_after_slide_transition"]=identity.CurrentQuote!=initial;window.Hide();Application.DoEvents();checks["hidden_planner_stops_quote_timer"]=!identity.QuoteTimerRunning;window.Show();Application.DoEvents();checks["visible_planner_restarts_quote_timer"]=identity.QuoteTimerRunning;window.WindowState=FormWindowState.Minimized;Application.DoEvents();checks["minimized_planner_stops_quote_timer"]=!identity.QuoteTimerRunning;window.WindowState=FormWindowState.Normal;Application.DoEvents();checks["restored_planner_restarts_quote_timer"]=identity.QuoteTimerRunning;using(var b=new Bitmap(window.Width,window.Height)){window.DrawToBitmap(b,window.ClientRectangle);b.Save(Path.Combine(dir,"preview-themed-planner.png"));}File.WriteAllText(report,JsonSerializer.Serialize(new{ok=checks.Values.All(x=>x),checks,external_requests=0},new JsonSerializerOptions{WriteIndented=true}));}
}
